static int __init c6xdigio_init_driver(void)
{
	int ret;

	ret = pnp_register_driver(&c6xdigio_pnp_driver);
	if (ret)
		return ret;

	ret = comedi_driver_register(&c6xdigio_driver);
	if (ret) {
		pnp_unregister_driver(&c6xdigio_pnp_driver);
		return ret;
	}

	return 0;
}
module_init(c6xdigio_init_driver);

static void __exit c6xdigio_exit_driver(void)
{
	comedi_driver_unregister(&c6xdigio_driver);
	pnp_unregister_driver(&c6xdigio_pnp_driver);
}
module_exit(c6xdigio_exit_driver);

MODULE_AUTHOR("Comedi https://www.comedi.org");

